<header class="admin-header"><div><p class="eyebrow">Overview</p><h1>Dashboard</h1></div><a class="button" href="<?= e(url('admin/posts/create')) ?>">New post</a></header><div class="stats"><?php foreach(['total'=>'Total posts','published'=>'Published','drafts'=>'Drafts','scheduled'=>'Scheduled'] as $key=>$label):?><section class="stat card"><span><?= e($label) ?></span><strong><?= (int)($counts[$key]??0) ?></strong></section><?php endforeach?></div><section class="panel"><h2>Recently updated</h2><?php if(!$items):?><p class="muted">No posts yet.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Title</th><th>Status</th><th>Updated</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><a href="<?= e(url('admin/posts/'.$item['id'].'/edit')) ?>"><?= e($item['title']) ?></a></td><td><span class="badge"><?= e($item['status']) ?></span></td><td><?= e(date('M j, Y',strtotime($item['updated_at']))) ?></td></tr><?php endforeach?></tbody></table></div><?php endif?></section>
